```graphql
{
  projects(filter: {name: {contains: "Harbor"}}) {
    nodes {
      id
      name
      url
      description
      documents {
        nodes {
          id
          title
          updatedAt
          lastEditor { name id }
          creator { name }
        }
        totalCount
      }
    }
  }
}
```

